/* Solo lectura. Ejecutar en la base donde corre el procedimiento.
   No inicia SF_CFDI_OPEN_ITEMS, no crea indices y no actualiza estadisticas.
   Las DMV de otras sesiones requieren permisos de estado/rendimiento del servidor.
   Si se conoce la sesion lenta, asignar su numero a @SPID.
*/
SET NOCOUNT ON;
DECLARE @SPID int = NULL;
SELECT DB_NAME() AS BaseActual, compatibility_level
FROM sys.databases WHERE database_id=DB_ID();

-- Tamano aproximado, sin COUNT(*) sobre los millones de detalles.
SELECT S.name AS Esquema,T.name AS Tabla,SUM(P.rows) AS FilasAproximadas
FROM sys.tables T JOIN sys.schemas S ON S.schema_id=T.schema_id
JOIN sys.partitions P ON P.object_id=T.object_id AND P.index_id IN (0,1)
WHERE (S.name='T3' AND T.name IN
 ('FACTURA_GENERAL','FACTURA_DETALLE','PREVENTA_GENERAL','PREVENTA_DETALLE',
  'CLIENTE','CFDI_COBRANZA','CFDI_HISTORIA_DOCTO_PAC','CFDI_DOCUMENTOS'))
 OR (S.name='EAI' AND T.name='CFDI_OPEN_ITEMS')
GROUP BY S.name,T.name;

-- Una fila por columna de indice; revisar orden y INCLUDE, no solo el nombre.
SELECT S.name AS Esquema,T.name AS Tabla,I.name AS Indice,I.type_desc,
       I.is_disabled,I.has_filter,I.filter_definition,
       IC.key_ordinal,IC.is_included_column,C.name AS Columna
FROM sys.tables T JOIN sys.schemas S ON S.schema_id=T.schema_id
JOIN sys.indexes I ON I.object_id=T.object_id
JOIN sys.index_columns IC ON IC.object_id=I.object_id AND IC.index_id=I.index_id
JOIN sys.columns C ON C.object_id=IC.object_id AND C.column_id=IC.column_id
WHERE (S.name='T3' AND T.name IN
 ('FACTURA_GENERAL','FACTURA_DETALLE','PREVENTA_GENERAL','PREVENTA_DETALLE',
  'CLIENTE','CFDI_COBRANZA','CFDI_HISTORIA_DOCTO_PAC','CFDI_DOCUMENTOS'))
 OR (S.name='EAI' AND T.name='CFDI_OPEN_ITEMS')
ORDER BY S.name,T.name,I.name,IC.is_included_column,IC.key_ordinal,IC.index_column_id;

-- Antiguedad/muestreo: un plan malo tambien puede deberse a estimaciones.
SELECT OBJECT_SCHEMA_NAME(S.object_id) AS Esquema,OBJECT_NAME(S.object_id) AS Tabla,
       S.name AS Estadistica,P.last_updated,P.rows,P.rows_sampled,P.modification_counter
FROM sys.stats S OUTER APPLY sys.dm_db_stats_properties(S.object_id,S.stats_id) P
WHERE S.object_id IN (OBJECT_ID('T3.Factura_General'),OBJECT_ID('T3.Factura_Detalle'),
 OBJECT_ID('T3.Preventa_General'),OBJECT_ID('T3.Preventa_Detalle'),OBJECT_ID('T3.Cliente'),
 OBJECT_ID('T3.CFDI_Cobranza'),OBJECT_ID('EAI.CFDI_OPEN_ITEMS'));

BEGIN TRY
    SELECT R.session_id,R.status,R.command,R.cpu_time,R.total_elapsed_time,
           R.logical_reads,R.reads,R.writes,R.wait_type,R.wait_time,
           R.blocking_session_id,R.wait_resource,
           SUBSTRING(T.text,(R.statement_start_offset/2)+1,
             ((CASE R.statement_end_offset WHEN -1 THEN DATALENGTH(T.text)
                ELSE R.statement_end_offset END-R.statement_start_offset)/2)+1) AS SentenciaActual
    FROM sys.dm_exec_requests R
    OUTER APPLY sys.dm_exec_sql_text(R.sql_handle) T
    WHERE R.session_id<>@@SPID AND R.database_id=DB_ID()
      AND (@SPID IS NULL OR R.session_id=@SPID);
    -- Plan compilado de la solicitud seleccionada; no es un plan real con filas.
    IF @SPID IS NOT NULL
        SELECT R.session_id,P.query_plan FROM sys.dm_exec_requests R
        OUTER APPLY sys.dm_exec_query_plan(R.plan_handle) P WHERE R.session_id=@SPID;
END TRY
BEGIN CATCH
    SELECT ERROR_MESSAGE() AS DiagnosticoDMVNoDisponible;
END CATCH;

/* PROPUESTAS: solo devuelve texto DDL. No ejecutar todas automaticamente.
   Comparar con indices reales: un indice equivalente con otro nombre sirve.
   Elegir segun plan/lecturas y costo de almacenamiento y escritura.
   La creacion en tablas grandes debe programarse: puede bloquear y consumir log.
   FG/PG por Factura apoyan etapa 90; NO agregarle corte por fecha, pues cambia
   el cliente facturado de documentos antiguos que vienen de cartera SAP.
*/
SELECT Prioridad, Uso,
  'SET ANSI_NULLS ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON; SET CONCAT_NULL_YIELDS_NULL ON; SET QUOTED_IDENTIFIER ON; SET NUMERIC_ROUNDABORT OFF; ' + DDL_Propuesto AS DDL_Propuesto
FROM (VALUES
 (1,'Busqueda de abiertos / exclusion temprana',
  'CREATE INDEX IX_OI_NotaVenta ON EAI.CFDI_OPEN_ITEMS(Nota_Venta);'),
 (1,'Cabeceras de factura por clase y fecha',
  'CREATE INDEX IX_OI_FG_TipoFecha ON T3.Factura_General(Tipo_Docto,Fecha_Factura) INCLUDE(Factura,Cliente_SAP,Ctro);'),
 (1,'Detalle de facturas candidatas',
  'CREATE INDEX IX_OI_FD_Factura ON T3.Factura_Detalle(Factura) INCLUDE(Valor_Subt,Valor_IVA,Credito_Subt,Credito_IVA,Envio_Subt,Envio_IVA);'),
 (1,'Cobranza de ventas',
  'CREATE INDEX IX_OI_Cobranza_Factura ON T3.CFDI_Cobranza(Factura) INCLUDE(Importe);'),
 (1,'Cobranza de notas',
  'CREATE INDEX IX_OI_Cobranza_NotaCredito ON T3.CFDI_Cobranza(Nota_Credito) INCLUDE(Importe);'),
 (2,'Cabeceras de preventa procesadas y vigentes',
  'CREATE INDEX IX_OI_PG_ClaseFecha ON T3.Preventa_General(Clase_Factura,Fecha_Factura) INCLUDE(Factura,Cliente_SAP,Ctro,Fecha_Proc_BATMD,Fecha_Cancelacion) WHERE Fecha_Proc_BATMD IS NOT NULL AND Fecha_Cancelacion IS NULL;'),
 (2,'Detalle de preventas candidatas',
  'CREATE INDEX IX_OI_PD_Factura ON T3.Preventa_Detalle(Factura) INCLUDE(Valor_Subt,Valor_IVA,Credito_Subt,Credito_IVA,Envio_Subt,Envio_IVA);'),
 (2,'Vigencias del cliente',
  'CREATE INDEX IX_OI_Cliente_SAPVigencia ON T3.Cliente(Cliente_SAP,Fecha_Ini_Vig) INCLUDE(Fecha_Fin_Vig,RFC);'),
 (2,'Traduccion a documento fiscal',
  'CREATE INDEX IX_OI_PAC_NotaVenta ON T3.CFDI_Historia_Docto_PAC(Nota_Venta) INCLUDE(Nota_Venta_CFDI);'),
 (2,'UUID por documento',
  'CREATE INDEX IX_OI_CFD_NotaVenta ON T3.CFDI_Documentos(Nota_Venta) INCLUDE(Folio_Fiscal,Metodo_Pago);'),
 (3,'Cliente facturado en etapa 90, factura',
  'CREATE INDEX IX_OI_FG_FacturaCliente ON T3.Factura_General(Factura) INCLUDE(Cliente_SAP,Clte_Factura_SAP);'),
 (3,'Cliente facturado en etapa 90, preventa',
  'CREATE INDEX IX_OI_PG_FacturaCliente ON T3.Preventa_General(Factura) INCLUDE(Cliente_SAP,Clte_Factura_SAP);')
) X(Prioridad,Uso,DDL_Propuesto) ORDER BY Prioridad,Uso;

